public class StringBuildBenchmark {static String plus(int n){String s="";for(int i=0;i<n;i++)s+="field"+i+"|";return s;}static String builder(int n){StringBuilder b=new StringBuilder();for(int i=0;i<n;i++)b.append("field").append(i).append('|');return b.toString();}static String buffer(int n){StringBuffer b=new StringBuffer();for(int i=0;i<n;i++)b.append("field").append(i).append('|');return b.toString();}static long time(java.util.concurrent.Callable<String> c)throws Exception{long t=System.nanoTime();String s=c.call();if(s.isEmpty())throw new AssertionError();return System.nanoTime()-t;}public static void main(String[]a)throws Exception{int n=a.length==0?1000:Integer.parseInt(a[0]);for(int i=0;i<3;i++){System.out.println("plus ns "+time(()->plus(n)));System.out.println("StringBuilder ns "+time(()->builder(n)));System.out.println("StringBuffer ns "+time(()->buffer(n)));}}}